mapper.select:
SELECT a.ID AS "ID", a.DATASOURCE_NAME AS "DATASOURCE_NAME", a.TYPE AS "TYPE", a.IP AS "IP", a.PORT AS "PORT", b.ID as "DATABASE_ID", b.DBNAME AS "DBNAME", b.SCHEMA_NAME AS "SCHEMA_NAME", b.USERNAME AS "USERNAME", b.PASSWORD AS "PASSWORD", b.STATE AS "STATE", b.DRIVERCLASS_NAME AS "DRIVERCLASS_NAME", b.DATASOURCE_URL AS "DATASOURCE_URL" FROM seo.seo_datasource a LEFT JOIN seo.seo_datasource_database b on a.ID = b.SOURCE_ID where 1=1
AND a.ID = #{params.ID}
AND b.ID = #{params.DATABASE_ID}
AND a.DATASOURCE_NAME like '%${params.DATASOURCE_NAME}%'
AND b.DRIVERCLASS_NAME like '%${params.DRIVERCLASS_NAME}%'
AND b.DATASOURCE_URL like '%${params.DATASOURCE_URL}%'
AND a.TYPE = #{params.TYPE}
AND a.CREATE_TIME >= #{params.BEGIN_TIME}
AND a.CREATE_TIME <= #{params.END_TIME}
AND a.CREATE_USER = #{params.CREATE_USER}
AND b.STATE = #{params.STATE}
AND b.DBNAME like '%${params.DBNAME}%'
AND a.IP like '%${params.IP}%'
AND a.PORT like '%${params.PORT}%'
order by a.DATASOURCE_NAME,a.TYPE,a.IP,a.PORT,b.CREATE_TIME DESC LIMIT ${params.rows} OFFSET ${params.page}

SELECT count(*) FROM
seo.seo_datasource a LEFT JOIN  seo.seo_datasource_database b on a.ID = b.SOURCE_ID
where 1=1

    AND a.ID = #{params.ID}


    AND b.ID = #{params.DATABASE_ID}


    AND a.DATASOURCE_NAME like '%${params.DATASOURCE_NAME}%'


    AND b.DRIVERCLASS_NAME like '%${params.DRIVERCLASS_NAME}%'


    AND b.DATASOURCE_URL like '%${params.DATASOURCE_URL}%'


    AND a.TYPE = #{params.TYPE}


    AND a.CREATE_TIME >= #{params.BEGIN_TIME}


    AND a.CREATE_TIME <= #{params.END_TIME}


    AND a.CREATE_USER = #{params.CREATE_USER}


    AND b.STATE = #{params.STATE}


    AND b.DBNAME like '%${params.DBNAME}%'


    AND a.IP like '%${params.IP}%'


    AND a.PORT like '%${params.PORT}%'

SELECT a.ID AS "ID", a.DATASOURCE_NAME AS "DATASOURCE_NAME", a.TYPE AS "TYPE", a.IP AS "IP", a.PORT AS "PORT", b.ID AS "DATABASE_ID", b.DBNAME AS "DBNAME", b.SCHEMA_NAME AS "SCHEMA_NAME", b.USERNAME AS "USERNAME", b.PASSWORD AS "PASSWORD", b.STATE AS "STATE", b.DRIVERCLASS_NAME AS "DRIVERCLASS_NAME", b.DATASOURCE_URL AS "DATASOURCE_URL", b.CREATE_TIME AS "CREATE_TIME" FROM seo.seo_datasource a LEFT JOIN seo.seo_datasource_database b on a.ID = b.SOURCE_ID where 1=1
AND a.ID = #{params.ID}
AND b.ID = #{params.DATABASE_ID}
AND a.DATASOURCE_NAME like '%${params.DATASOURCE_NAME}%'
AND b.DRIVERCLASS_NAME like '%${params.DRIVERCLASS_NAME}%'
AND b.DATASOURCE_URL like '%${params.DATASOURCE_URL}%'
AND a.TYPE = #{params.TYPE}
AND a.CREATE_TIME >= #{params.BEGIN_TIME}
AND a.CREATE_TIME <= #{params.END_TIME}
AND a.CREATE_USER = #{params.CREATE_USER}
AND b.STATE = #{params.STATE}
AND b.DBNAME like '%${params.DBNAME}%'
AND a.IP like '%${params.IP}%'
AND a.PORT like '%${params.PORT}%'
order by a.DATASOURCE_NAME,a.TYPE,a.IP,a.PORT,b.CREATE_TIME DESC

SELECT a.ID as "ID", a.SOURCE_ID as "SOURCE_ID", a.DBNAME as "DBNAME", a.SCHEMA_NAME as "SCHEMA_NAME", a.USERNAME as "USERNAME", a.PASSWORD as "PASSWORD", a.STATE as "STATE", a.DRIVERCLASS_NAME as "DRIVERCLASS_NAME", a.DATASOURCE_URL as "DATASOURCE_URL", a.CREATE_TIME as "CREATE_TIME", a.CREATE_USER as "CREATE_USER" FROM seo.seo_datasource_database a where 1=1
AND a.SOURCE_ID = #{params.SOURCE_ID}
AND a.DBNAME = #{params.DBNAME}
AND a.SCHEMA_NAME = #{params.SCHEMA_NAME}

SELECT *
FROM
seo.seo_datasource a
where 1=1

    AND a.ID != #{params.ID}


    AND a.DATASOURCE_NAME = #{params.DATASOURCE_NAME}
